contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount, uint extra) public payable {
        require(amount == 10 ether);
        require(address(this).balance >= amount);
        // Advance pastBlockTime beyond current timestamp by succeeding first (if needed)
        bool first;
        if (c.pastBlockTime() >= block.timestamp) {
            // can't succeed now; just proceed to the reversion check
            first = false;
        } else {
            c.f{value: amount}();
            first = true;
        }
        uint before = c.pastBlockTime();
        bool reverted;
        if (!first) {
            // state already blocks success; verify fallback with 10 ether reverts
            reverted = true;
            try c.f{value: amount}() { reverted = false; } catch { reverted = true; }
            assert(reverted && c.pastBlockTime() == before);
        } else {
            assert(before == c.pastBlockTime() && before > 0);
            try c.f{value: amount}() { reverted = false; } catch { reverted = true; }
            assert(reverted && c.pastBlockTime() == before);
        }
        extra;
    }
    receive() external payable {}
}

